package pe.edu.utp.eventope.controller;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import pe.edu.utp.eventope.config.*;import pe.edu.utp.eventope.dto.*;import pe.edu.utp.eventope.dao.CompraDAO;import java.io.IOException;import java.sql.*;import java.util.Optional;
@WebServlet("/compras/confirmacion")
public final class ConfirmacionCompraServlet extends HttpServlet {
 private ProveedorConexion db;public void init()throws ServletException{try{db=new ConexionBD(Configuracion.cargar());}catch(RuntimeException e){throw new ServletException("No se pudo configurar la confirmación",e);}}
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{Object a=req.getSession().getAttribute("sesionUsuario");if(!(a instanceof SesionUsuario actor)||actor.getTipo()!=SesionUsuario.Tipo.CLIENTE){resp.sendError(401);return;}int id;try{id=Integer.parseInt(req.getParameter("id"));if(id<=0)throw new NumberFormatException();}catch(Exception e){resp.sendError(404);return;}try(Connection c=db.abrir();PreparedStatement p=c.prepareStatement("SELECT t.id,t.codigo_unico,t.total,e.nombre,cp.serie_correlativo,(SELECT COUNT(*) FROM detalle_transaccion d WHERE d.transaccion_id=t.id) cantidad FROM transaccion_compra t JOIN evento_cultural e ON e.id=t.evento_id JOIN comprobante_pago cp ON cp.transaccion_id=t.id WHERE t.id=? AND t.cliente_id=? AND t.estado='CONFIRMADA'")){p.setInt(1,id);p.setInt(2,actor.getId());try(ResultSet r=p.executeQuery()){if(!r.next()){resp.sendError(404);return;}CompraConfirmada compra=new CompraConfirmada(r.getInt("id"),r.getString("codigo_unico"),r.getString("serie_correlativo"),r.getString("nombre"),r.getBigDecimal("total"),r.getInt("cantidad"));req.setAttribute("compra",compra);req.getRequestDispatcher("/WEB-INF/views/compras/confirmacion.jsp").forward(req,resp);}}catch(SQLException e){throw new ServletException("No se pudo consultar el comprobante",e);}}
}
